CREATE TABLE IF NOT EXISTS guests(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,event TEXT NOT NULL DEFAULT '',profile TEXT NOT NULL DEFAULT '{}',research TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'active',calls INTEGER NOT NULL DEFAULT 0,lookups INTEGER NOT NULL DEFAULT 0,next_action TEXT NOT NULL DEFAULT '',due_date TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY,guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE,email TEXT NOT NULL,name TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',consented_at TEXT,provider_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS limits(k TEXT PRIMARY KEY,n INTEGER NOT NULL,until INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS drafts_guest ON drafts(guest_id);
